import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Lenguajes — el que el trabajo pida","description":"Python, JavaScript/TypeScript, Go, PHP, C#, SQL, C/C++ y lenguajes PLC — preparación de producción honesta en nueve lenguajes.","frontmatter":{"title":"Lenguajes — el que el trabajo pida","description":"Python, JavaScript/TypeScript, Go, PHP, C#, SQL, C/C++ y lenguajes PLC — preparación de producción honesta en nueve lenguajes."},"headers":[],"relativePath":"es/skills/languages/index.md","filePath":"es/skills/languages/index.md"}`),a={name:`es/skills/languages/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="lenguajes-—-el-que-el-trabajo-pida" tabindex="-1">Lenguajes — el que el trabajo pida <a class="header-anchor" href="#lenguajes-—-el-que-el-trabajo-pida" aria-label="Permalink to “Lenguajes — el que el trabajo pida”">​</a></h1><p>Rechazo la religión del &quot;único lenguaje verdadero&quot;. Los lenguajes son herramientas con formas, y el trabajo decide cuál encaja. Estos porcentajes son autoevaluaciones honestas de preparación de producción — no certificados de cursos.</p><table tabindex="0"><thead><tr><th>Lenguaje</th><th>Preparación</th><th>Dónde lo uso</th></tr></thead><tbody><tr><td>Python</td><td>99%</td><td>Puentes de API, agentes, automatización, scraping — GhostBrain, Hermes, paneles.</td></tr><tr><td>JavaScript / TypeScript</td><td>98%</td><td>Web full-stack, Workers de borde, paneles, este portafolio.</td></tr><tr><td>PHP</td><td>98%</td><td>Servicios Laravel, despliegues clásicos, productos rápidos para clientes.</td></tr><tr><td>SQL</td><td>100%</td><td>Diseño de esquemas, afinado, reporting sobre Postgres/MySQL.</td></tr><tr><td>Ladder (LD)</td><td>96%</td><td>Lógica PLC en líneas de producción reales.</td></tr><tr><td>Texto Estructurado (ST)</td><td>96%</td><td>Programas de control industrial IEC 61131-3.</td></tr><tr><td>Go</td><td>94%</td><td>NetPilot, OmniRouter, glm-free-api — CLIs y servicios.</td></tr><tr><td>C#</td><td>93%</td><td>Backends .NET, herramientas de escritorio, WPF/MAUI.</td></tr><tr><td>C / C++</td><td>78%</td><td>HardwarePT, experimentos embebidos, núcleos de rendimiento.</td></tr></tbody></table><p>El patrón tras la lista: lenguajes de alto nivel para velocidad, lenguajes de sistemas para control, y lenguajes industriales porque alguien tiene que hacer que el mundo físico se comporte. Un lenguaje nuevo es un problema de fin de semana, no una decisión de carrera — el <a href="/Usf/es/agentic/overview/">flujo agéntico</a> abarata aún más el ramp-up, ya que los agentes escriben scaffolding idiomático en cualquier ecosistema mientras yo aportó el juicio.</p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};